from author import *
c =C ('命题逻辑')
add (c ,'课程知识地图',[('起点','从真假、分组和连线开始')],[P ('欢迎来到一小时学完离散数学。这节课面向第一次接触这些符号的大学生。我们先用真值表整理一句话的真假，再用集合分组、关系连线和计数解决小问题，最后学习图、树和简单代数结构。你不需要先学会高等数学。每章安排一道小题，讲完后留四秒思考，再核对答案。先看例子中对象怎样变化，再记住公式和名称。不同学校范围可能略有区别，今天建立的是一张常见基础内容的学习地图。',1 ,['零基础，从具体例子开始','10章、10题，逐步核对'])],kind ='overview')
L (c ,'什么句子可以判断真假',('命题','今天下雨：在确定时间地点后可判断真假'),('非命题','请关门；x大于3但未指定x'),
'先看一句话：今天下雨。在时间和地点已经确定后，这句话有明确的真假，我们把能判断真假的陈述句叫命题。命题为真还是为假，与它能不能成为命题是两件事。比如二加二等于五虽然是假的，仍然是命题。我们常用一个字母代替整句话，方便把几句话的组合规则单独研究，不必每次重复很长的文字。',
'再看请关门，它是在发出要求，通常没有真假，所以不是命题。还有一个数大于三，如果没有告诉你这个数是多少，也没有说明对哪些数讨论，就暂时不能确定真假。遇到题目，先问是否为陈述，条件和讨论对象是否明确，再判断真假。不要因为一句话含有数学符号，就自动把它当成已经确定的命题。',['先判断能否确定真假','假命题仍然是命题'],['请求句不判断真假','未指定变量先明确范围'])
L (c ,'非、且、或',('规则',r'$\neg p,\quad p\land q,\quad p\lor q'),('例子',r'$p=1,\ q=0:\quad \neg p=0,\ p\land q=0,\ p\lor q=1'),
'把下雨记成一个命题，把带伞记成另一个命题。非表示把真假翻过来；且要求两句话都真；或要求至少一句真。这里的或默认允许两句同时为真，与日常语言里有时表示二选一的说法不同。我们用一代表真、零代表假，但这些数字在这里表示逻辑状态，不是直接拿来做普通加法。先把三个规则记清楚，后面的真值表就有依据。',
'现在依次检查四组真假。两句都真时，且与或都真；只有一句真时，且为假而或为真；两句都假时，两者都假。否定只看自己对应的那句话，原来真就变假，原来假就变真。填表时先列输入，再逐列计算，复杂表达式可以增加中间列。不要跳着凭直觉填最后一格，也不要把逻辑或误当成只能一个为真。',['否定翻转，且要求全真','逻辑或允许两句都真'],['先列全部输入组合','逐列计算中间结果'],visual =V ('truth',op ='basic'),anchors =[None ,'现在依次检查四组真假'])
L (c ,'如果与只有当',('蕴含',r'$p\to q\ \equiv\ \neg p\lor q'),('唯一的假情况',r'$p=1,\ q=0\quad\Longrightarrow\quad(p\to q)=0'),
'如果下雨，那么带伞，可以理解为作出一条承诺：只要下雨，就会带伞。下雨却没带伞，承诺被违反，所以这时整个如果句是假。没有下雨时，这句话没有规定一定带伞还是不带伞，在命题逻辑的规则中，两种情况都不算违反。这个约定叫实质蕴含，先记住只有前真后假这一行是假，就能准确填表。',
'中文翻译还要分清方向。只有买票才能入场，表示入场一定已经买票，因此入场放在箭头前面，买票放在后面。买票是入场的必要条件，却未必保证一定入场。如果买票就能入场，则买票放前面，它表达充分条件。判断箭头时可以找一个违反规定的场景，把必要与充分的角色写出来，比只盯着句子先后顺序可靠。',['蕴含仅前真后假为假','前件假时不算违反承诺'],['只有q才p，写p指向q','必要与充分注意方向'],visual =V ('truth',op ='imp'),anchors =['只要下雨，就会带伞',None ])
L (c ,'等价式与德摩根律',('德摩根律',r'$\neg(p\land q)\equiv\neg p\lor\neg q'),('另一种形式',r'$\neg(p\lor q)\equiv\neg p\land\neg q'),
'两种表达式在每一组输入下都有相同真假，就叫逻辑等价。例如，并非两个人都到场，表示至少有一个人没有到场，而不是两个人都没到场。把否定推进括号时，里面的且要变成或，每个命题也都要否定。这就是第一条德摩根律。把文字翻成一个两人的小场景，往往比直接背一串符号更容易发现错误。',
'另一条规律是，并非至少有一个人到场，就意味着两个人都没到场。因此外面的否定进入或表达式后，要把或变成且，再分别否定。你可以把两边真值表并排比较，四行都一致才算等价，只检查一行不够。双重否定则回到原命题。化简时每一步只用一条明确规律，保留中间式，方便发现漏掉的否定。',['否定进入括号要换连接词','不是全到，不等于全不到'],['真值表每一行都要相同','双重否定回到原命题'],visual =V ('truth',op ='demorgan'),anchors =[None ,'把两边真值表并排比较'])
L (c ,'范式与有效推理',('从真行写析取范式',r'$p\leftrightarrow q\equiv(p\land q)\lor(\neg p\land\neg q)'),('肯定前件',r'$p,\quad p\to q\quad\Longrightarrow\quad q'),
'范式的名字看起来长，先抓住一件事：把真值表中结果为真的行，分别写成一个条件，再用或连起来。同真同假才成立的双向条件，就有两个人都真和两个人都假两种情况。每个小条件内部用且，整组情况之间用或，这是一种析取范式。若每项都包含所有变量，就是对应变量范围下的主析取范式。',
'推理则要检查，前提全真时能不能保证结论真。已知如果下雨就带伞，又已知确实下雨，可以推出带伞，这叫肯定前件。可是只知道带伞，不能反推一定下雨，因为晴天也可能带伞。找一组让前提全真、结论为假的赋值，就能否定推理的有效性。做题时把前提和结论分开，别把一句正确的蕴含随意倒过来。',['真行逐项写条件，再用或连接','主范式每项包含全部变量'],['前提真时结论必须真','肯定后件不能保证有效'])
Q (c ,'判断蕴含与逆推',('已知',r'$p=0,\quad q=1'),('问题','p指向q的真假；由q能否推出p'),
'设下雨这个命题为假，带伞这个命题为真。如果下雨就带伞这句话是真是假。另外，单凭带伞和如果下雨就带伞，能不能推出下雨。请分别回答，不要把两个问题混成一个。第一个按真值表判断，第二个找一个前提成立而结论不成立的场景。接下来留四秒给你思考。',
'第一问是真的，因为蕴含只有前真后假时为假，当前前件是假，没有落入那一行。第二问不能推出下雨。现在这个晴天带伞的场景，本身就让带伞与如果句都成立，却让下雨为假，所以它是逆推无效的反例。真假计算和推理有效性是两个层次，写答案时最好分别标清楚。',('答案','蕴含为真；不能由q倒推p'),('依据','前件假；晴天带伞构成反例'))

c =C ('谓词、量词与证明')
L (c ,'先确定讨论对象',('谓词',r'$P(x):\ x>2'),('论域改变结论','在正整数中讨论；在全体整数中讨论'),
'一个数大于二还没有指定这个数，因此我们先把它看成一个带位置的陈述，叫谓词。给这个位置放入三，得到三大于二，是真命题；放入一，得到假命题。这个位置允许放哪些对象，叫论域。论域可以是一个班的学生，也可以是整数或实数，题目中的同一个符号换了论域，结论就可能不同。',
'比如每个数都有一个更小的数，在全体整数中成立，给任何整数减一就行；在正整数中却不成立，因为一没有更小的正整数。看到带变量的题，第一步就在草稿上写出论域，再理解条件。别把题目中的整数自动扩大为实数，也别把正整数默认包含零。涉及这些边界时，以题目明确给出的集合为准。',['谓词先给变量留位置','论域限制可代入的对象'],['同一句话换论域可能变真假','先看整数、正整数或实数'])
L (c ,'任意与存在',('全称与存在',r'$\forall x\,P(x),\qquad\exists x\,P(x)'),('例子','所有学生及格；至少一名学生及格'),
'任意和存在是两种很重要的要求。说所有学生都及格，要检查每一名学生；说至少一名学生及格，只需要找到一个符合的学生。用符号写出来，倒过来的大写字母形状表示任意，反过来的字母形状表示存在。刚开始可以在符号下面写中文，不必强迫自己一下就认熟所有形状，关键是别把检查要求弄反。',
'现在逐个查看四名学生。证明所有人及格，四个都要通过；推翻所有人及格，找到一个不及格就够。证明至少有人及格，找一人即可；推翻它，却要确认所有人都不及格。这里一边的证据常常是另一边的反例。有限集合可以逐个检查，无限集合不能只列几个例子就声称已经证明了所有情况。',['全称要求每一个都满足','存在只需一个符合的对象'],['全称的反例只需一个','有限枚举不能替代无限证明'],visual =V ('quantifier'),anchors =[None ,'现在逐个查看四名学生'])
L (c ,'量词否定与先后顺序',('否定换量词',r'$\neg\forall x\,P(x)\equiv\exists x\,\neg P(x)'),('顺序不同',r'$\forall x\exists y\,(y>x)\quad;\quad\exists y\forall x\,(y>x)'),
'并非所有同学都及格，意思是存在一个同学不及格。并非存在一个同学及格，则意味着所有同学都不及格。否定穿过量词时，全称与存在交换，后面的判断也要取反。若判断是大于，否定通常是小于或等于，别只写成小于。每推进一层否定就处理一层量词，最后再检查里面的条件。',
'量词的先后顺序也不能随意交换。在整数中，对每个数都能找到一个更大的数，这句话成立，后面选的数可以根据前面那个数改变。但存在同一个整数，比所有整数都大，就不成立。先任意再存在，允许按对象选择；先存在再任意，往往要求一个统一对象。把选人和选答案的顺序画出来，就能看清两个要求的差别。',['否定穿过量词要交换类型','大于的否定包含等于'],['对每个对象可各选一个','统一选一个再覆盖全部要求更强'])
L (c ,'直接证明与逆否证明',('直接证明',r'$a=2m,\ b=2n\ \Longrightarrow\ a+b=2(m+n)'),('逆否等价',r'$p\to q\ \equiv\ \neg q\to\neg p'),
'证明两个偶数相加仍是偶数，可以从定义出发。把两个数分别写成二乘一个整数，相加后提出二，括号里面仍是整数，因此和也是二的整数倍。这就是直接证明：从已知条件一步一步走到目标。偶数的定义不是一个例子，而是能覆盖全部偶数的表达方式。只算二加四等于六，能帮助猜测，却不能覆盖所有偶数。',
'有些命题从反方向更容易处理，但要用逆否，不是随便倒箭头。要证明一个整数平方为偶数时原数必为偶数，可以证明原数若为奇数，平方也为奇数。把奇数写成二乘整数再加一，展开后仍是偶数加一。这样从非结论走到非前提，与原蕴含等价。逆命题只是交换前后，和逆否命题不是同一个东西。',['定义让证明覆盖所有情况','有限例子只能帮助猜测'],['逆否同时换方向并否定','不要把逆命题当成逆否命题'])
L (c ,'反证、反例与证明书写',('反证法','假设结论不成立，推出与已知矛盾'),('反例','否定全称命题，只需一个合格反例'),
'反证法先暂时假设结论不成立，再结合已知推出矛盾。例如假设最大的整数存在，把它加一就得到更大的整数，与最大这个要求冲突。这里不是只说我觉得不可能，而是把冲突明确指出来。证明时先写假设，再写推导，最后说明与哪一条条件矛盾，读者才能检查你的每一步，而不是只看到结论。',
'反例则专门用来推翻所有情况都成立的说法。比如所有素数都是奇数，数字二就是反例，因为二是素数却不是奇数。一个反例必须满足题目的前提，再违反结论，不能拿一个本来就不属于讨论范围的数来反驳。以后做判断题，先找边界、零、一和小规模对象，常能很快找到反例；找不到反例，也不等于已经证明为真。',['反证要写出具体矛盾','假设的是目标的否定'],['反例必须满足原前提','找不到反例不是证明'])
Q (c ,'否定全称命题',('原命题','本班所有学生至少选修一门课程'),('任务','写否定；说明证明原命题的检查要求'),
'原命题是，本班所有学生都至少选修一门课程。请用一句清楚的中文写出它的否定，再回答，找到一位选了课的同学，能不能证明原命题。注意所有与至少一门各在不同层，否定时要从外到内处理，不要写成所有同学都没选课。接下来留四秒思考。',
'否定是，存在一名本班学生，一门课程也没有选。外面的所有改为存在，里面的至少一门改为一门也没有。只找到一位选课的学生不能证明所有人都选了课，它只能证明至少有人选课。有限班级可以逐个核查全体学生，要否定原命题则找到一名未选课学生就够。答案既要交代对象，也要交代课程选择情况。',('答案','存在本班学生，一门课程也没选'),('检查','一人选课不足以证明全体选课'))

c =C ('集合与集合运算')
L (c ,'元素、子集与空集',('元素与子集',r'$1\in\{1,2\},\qquad\{1\}\subseteq\{1,2\}'),('空集',r'$\varnothing\subseteq A,\qquad |\varnothing|=0'),
'集合可以先理解为一组明确的对象。对象叫元素，属于符号连接一个元素和一个集合；子集符号则连接两个集合。数字一属于由一和二组成的集合，而只装着一的小集合，是这个集合的子集。集合里不考虑排列顺序，重复写同一个元素也不会多算一个。写花括号以后，对象的层次就变了，做题时要逐层看清楚。',
'没有元素的集合叫空集。空集是任何集合的子集，因为找不出一个空集里的元素违反子集要求。但空集未必是任意集合的元素，是否属于要看它有没有被明确装进去。空集与只装着空集的集合也不同，前者零个元素，后者一个元素。遇到花括号嵌套，先数最外层逗号分开的对象，再判断每个对象是什么。',['属于连接元素与集合','子集连接两个集合'],['空集零元素，装着空集则一元素','空集是子集不等于总是元素'])
L (c ,'并、交与差',('示例',r'$A=\{1,2,3\},\quad B=\{3,4\}'),('计算',r'$A\cup B=\{1,2,3,4\},\quad A\cap B=\{3\}'),
'把集合画成两个圆。并集把至少落在一个圆里的对象都收进来，交集只收同时落在两个圆里的对象。现在左边集合是一、二、三，右边是三、四，三处在重叠区域。并起来是一、二、三、四，交起来只有三。并集不是把元素数量直接相加，因为重叠的三只能算一次，画出位置能帮助你发现重复。',
'再看差集，左边减右边，保留属于左边却不属于右边的元素，因此得到一和二。反过来右边减左边，只剩四，两者通常不同。你可以把差集读成先站在前面的集合里，再排除后面的集合。运算顺序和括号都很重要，不要把差当成普通数的减法随意交换。检查一个具体元素是否留下，比一次性猜整组答案更稳。',['并集至少在一边，交集同时在两边','重叠元素只计一次'],['A减B保留A独有元素','交换差集顺序结果可能改变'],visual =V ('venn',mode ='operations'),anchors =['把集合画成两个圆','再看差集'])
L (c ,'补集与集合恒等式',('先固定全集',r'$U=\{1,2,3,4,5\},\quad A^c=U\setminus A'),('德摩根律',r'$(A\cup B)^c=A^c\cap B^c'),
'补集要先知道全集。全集是一到五，集合A是一、二、三，那么A的补集就是四和五。全集换了，补集也可能换，所以题目没有给清范围时，不能凭感觉补一串数。图中的矩形表示全集，圆外而矩形内才是补集，矩形外的空白不在讨论范围。差集和补集的关系，也可以理解为前者是在指定集合里做排除。',
'集合运算同样有德摩根律。不在两个集合并集中的元素，必须既不在左集合，也不在右集合，因此等于两个补集的交。验证恒等式，可以任选一个元素，把属于和不属于分别翻译成逻辑条件，也可以观察图中阴影区域。只拿一个具体集合算出相同结果，能检查例子，却不足以证明对所有集合都成立。',['补集必须指定全集','矩形外不在论域'],['集合运算可翻译成逻辑判断','恒等式要求对全部集合成立'],visual =V ('venn',mode ='complement'),anchors =['图中的矩形表示全集','观察图中阴影区域'])
L (c ,'幂集与笛卡尔积',('幂集',r'$\mathcal{P}(\{a,b\})=\{\varnothing,\{a\},\{b\},\{a,b\}\}'),('笛卡尔积',r'$\{1,2\}\times\{a,b\}=\{(1,a),(1,b),(2,a),(2,b)\}'),
'把一个集合的全部子集收在一起，得到幂集。原集合只有两个元素，每个元素可以选或者不选，组合起来有四种子集，包括什么也不选的空集，以及全部选中的原集合。因此有n个元素的有限集合，幂集大小是二的n次方。注意幂集的元素本身都是集合，写答案时最外层和内部的花括号都不能漏。',
'笛卡尔积则从前面的集合选一个对象，再从后面的集合选一个对象，组成有顺序的数对。先选一或二，再选字母a或b，共有四对。数对的第一和第二个位置有区别，交换通常得到不同对象。如果两个集合分别有m和n个元素，积集有m乘n个有序对。后面学习关系和函数，就会从这些可能的有序对中挑选一部分。',['幂集收集全部子集','空集和原集合都不能漏'],['有序对的位置不可随意交换','积集大小用乘法'],visual =V ('product'),anchors =[None ,'组成有顺序的数对'])
L (c ,'容斥与分类计数',('两个集合的容斥',r'$|A\cup B|=|A|+|B|-|A\cap B|'),('例子',r'$18+15-7=26'),
'班里十八人喜欢篮球，十五人喜欢足球，其中七人两项都喜欢。直接相加会把这七人重复算两遍，所以要减去一次重叠，至少喜欢一项的共有二十六人。这个公式叫两个集合的容斥。题目中的至少一项对应并集，两项都对应交集，只喜欢篮球则是十八减七。先把文字对应到区域，再计算会更清楚。',
'如果全班三十人，两项都不喜欢就是三十减二十六，得到四人。这里用到了明确的全班人数，也就是全集大小。换成三个集合时，还要考虑三者共同重叠被减过头，需要再加回来。入门题先把两个集合的四个互不重叠区域填完整，再检查总人数是否一致。出现负数或分区总和超过全班，通常说明交集与只喜欢被混用了。',['相加后减去重复交集','至少一项对应并集'],['都不喜欢用全集减并集','区域人数应非负且总和一致'],visual =V ('venn',mode ='count'),anchors =['所以要减去一次重叠',None ])
Q (c ,'集合人数练习',('已知','全班40人；A有22人，B有17人，两者都有8人'),('问题','至少属于一项的人数；两项都不属于的人数'),
'一个班四十人，参加活动A的有二十二人，参加活动B的有十七人，同时参加两项的有八人。至少参加一项的有多少人，两项都没参加的又有多少人。先把交集放进重叠区域，再处理并集与补集，不要直接用四十减二十二再减十七。接下来留四秒思考。',
'至少参加一项的人数是二十二加十七减八，得到三十一。两项都没有参加，是四十减三十一，得到九人。也可以分区检查：只参加A的十四人，只参加B的九人，同时参加的八人，再加两项都没有的九人，总共四十。用分区总数回查一次，能发现很多漏减重叠造成的错误。',('答案',r'$|A\cup B|=22+17-8=31'),('补集',r'$40-31=9'))
